def load_subclass_features():
    spec = importlib.util.spec_from_file_location("subclasses", f"{SCRATCHPAD}/tr_rogue-subclasses-2014.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return {
        f"block-section-features-1/item/{index}": module.FRAGMENTS[f"block-section-phantom-6/item/{index}"]
        for index in range(5)
    }


